def verifier_ip(s):
    if not isinstance(s, str):
        return False

    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part or not part.isdigit():
            return False

        if len(part) > 1 and part[0] == '0':
            return False

        if int(part) > 255:
            return False

    return True
```

