def convertir_octets(n):
    if n < 1024:
        return n, "B"
    elif n < 1024 ** 2:
        return round(n / 1024, 2), "Ko"
    elif n < 1024 ** 3:
        return round(n / (1024 ** 2), 2), "Mo"
    else:
        return round(n / (1024 ** 3), 2), "Go"
```

